from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
rows=[]
def add(n,p,m,stem,answer,rubric,mapping=None):rows.append(dict(number=n,page=p,marks=m,stem=stem,answer=answer,rubric=rubric,mapping=mapping))
add('1',2,6,'A teacher asks you to type favourite animal names, sort them alphabetically and show them on the monitor.\ni. Name the THREE data-processing stages. (3 marks)\nii. Describe each stage. (3 marks)','Input — names are entered using the keyboard.\nProcessing — the computer sorts the names alphabetically.\nOutput — the sorted list is displayed on the monitor.',['1 mark for each correct stage name, up to 3.','1 mark for correctly linking each stage to the scenario, up to 3.'])
add('2',3,3,'Give THREE reasons why lower memory access time is usually better.','Lower latency supplies requested data or instructions sooner. This reduces CPU waiting or stall time. It can improve application responsiveness and throughput for memory-dependent workloads.',['Award 1 mark for each distinct justified benefit, up to 3.','Accept equivalent explanations of faster data access, reduced processor waiting and improved workload performance. Do not award separate marks for merely repeating faster in three ways.'])
add('3',3,3,'Compare Intel Pentium IV and AMD Athlon processors by clock speed, cache and architecture.','The families contain multiple models, so the prompt does not establish one clock speed or cache size for either family. A defensible comparison identifies specific models or generations first. Pentium 4 uses Intel NetBurst. The original Athlon/Athlon XP generation uses AMD K7, while later Athlon generations differ. Clock rates and cache capacities must be tied to the chosen models.\n\nFor example, a comparison of the Willamette Pentium 4 generation and Thunderbird Athlon generation may discuss their different clock ranges and L2 cache designs, provided the stated figures match the named models.',['1 mark for a correct model-specific clock comparison.','1 mark for a correct model-specific cache comparison.','1 mark for an accurate architecture comparison.','The source does not identify processor models. Do not impose one universal clock or cache number or claim that a higher clock rate alone proves superior performance.'])
add('4',4,3,'State THREE primary functions of HDMI that distinguish it from a PS/2 port.','HDMI carries digital video to a display, carries digital audio, and combines audio and video over one cable for compatible equipment. PS/2 is a peripheral interface traditionally used for keyboard or mouse data.',['1 mark for digital video transfer.','1 mark for digital audio transfer.','1 mark for combined audio/video connectivity or another correct distinguishing HDMI capability.'])
add('5',4,3,'i. Give the full form of Wi-Fi. (1 mark)\nii. Identify its wireless transmission medium. (1 mark)\niii. Name one common place of use. (1 mark)','i. Many school texts expand Wi-Fi as Wireless Fidelity. Wi-Fi is also described by industry sources as a brand name rather than a formal acronym, so a technically accurate explanation should receive credit.\nii. Radio waves.\niii. A home, school, office, airport or café.',['1 mark for Wireless Fidelity in the textbook context, or for correctly explaining the naming issue.','1 mark for radio waves.','1 mark for any suitable common use location.'])
add('6',5,3,'Compare DBMS and a traditional file-management system in data security, data retrieval and data redundancy.','| Aspect | DBMS | Traditional files |\n| --- | --- | --- |\n| Security | Central permissions and access controls can protect shared data. | Protection depends on file permissions and each application. |\n| Retrieval | Structured queries can retrieve and combine records flexibly. | Application code commonly implements searches in individual files. |\n| Redundancy | Shared data and normalisation can reduce duplication. | Separate application files often duplicate data. |',['1 mark for each valid paired comparison, up to 3.','Credit qualified comparisons. A DBMS does not automatically eliminate all duplication or guarantee security.'],'12:11.9.1')
add('7a',6,7,'i. Define unguided transmission. (1 mark)\nii. Give TWO advantages and TWO disadvantages. (4 marks)\niii. Name and describe ONE unguided medium. (2 marks)','Unguided transmission sends electromagnetic signals through free space without a physical cable guiding the path.\n\nAdvantages include user mobility and deployment without running cables to every endpoint. Disadvantages include interference and exposure to interception unless suitable security is used.\n\nRadio waves are one example. An antenna radiates modulated signals through the air to a receiver, as in wireless local-area networking.',['1 mark for a definition stating wireless/free-space propagation.','1 mark for each distinct valid advantage, up to 2.','1 mark for each distinct valid disadvantage, up to 2.','1 mark for a suitable medium and 1 mark for its correct description.'])
add('7b',6,7,'i. Describe geostationary Earth orbit. (2 marks)\nii. Give TWO advantages of a GEO satellite. (2 marks)\niii. Give THREE applications. (3 marks)','A geostationary satellite follows a circular orbit above the equator in the direction of Earth’s rotation with a period equal to Earth’s rotation period. It appears fixed above one longitude.\n\nAdvantages include a stable apparent direction for ground antennas and continuous coverage of a large region within its footprint.\n\nApplications include television broadcasting, communications/data relays and continuous regional weather observation.',['1 mark for an equatorial orbit with Earth-matching rotation and 1 mark for its stationary apparent position.','1 mark for each correct advantage, up to 2.','1 mark for each distinct suitable application, up to 3.'])
add('8a',7,7,'The library database shows Authors(Author_ID, Name, Nationality), Users(User_ID, Name, Membership_Status) and Books(ISBN, Title, Published_Year). Books can have multiple authors, and users can borrow multiple books. Draw an ERD.','Use the three supplied entities with their primary keys. Resolve book–author authorship through an associative entity. Record loans using a Borrowing entity so different users can borrow a book over time.\n\n```text\nAuthors 1 ───< BookAuthors >─── 1 Books\nUsers   1 ───< Borrowings >─── 1 Books\n\nAuthors(Author_ID PK, Name, Nationality)\nBooks(ISBN PK, Title, Published_Year)\nUsers(User_ID PK, Name, Membership_Status)\nBookAuthors(Author_ID PK/FK, ISBN PK/FK)\nBorrowings(Loan_ID PK, User_ID FK, ISBN FK)\n```\n\nA suitable loan identifier supports repeated loans. If physical copies matter, a separate Copies entity can be added, but the source does not require it.',['1 mark each for the three supplied entities with appropriate primary keys, up to 3.','1 mark for the authorship relationship and 1 for correctly resolving its many-to-many form.','1 mark for a valid user–book loan relationship and 1 for consistent cardinalities and foreign keys.','Accept equivalent logically consistent ERDs and explicit assumptions. The original wording does not specify every minimum participation constraint.'])
add('8b',8,7,'Write MS Access SQL to create Product with Product_ID TEXT(5) as primary key, Product_Name TEXT(25), Price, Stock_Quantity and Category TEXT(20). Then remove Category, add Brand with length 15, and expand Product_Name to 40 characters.','```sql\nCREATE TABLE Product (\n    Product_ID TEXT(5) CONSTRAINT PK_Product PRIMARY KEY,\n    Product_Name TEXT(25),\n    Price CURRENCY,\n    Stock_Quantity INTEGER,\n    Category TEXT(20)\n);\n\nALTER TABLE Product DROP COLUMN Category;\nALTER TABLE Product ADD COLUMN Brand TEXT(15);\nALTER TABLE Product ALTER COLUMN Product_Name TEXT(40);\n```\n\nExecute each statement separately in Access. The supplied examples are P101 / Penu Chicken Nuggets / 1580.00 / 74 / Frozen Item, P102 / Tesle Milkrak / 1920.50 / 25 / Dairy, and P103 / Mapple Smart Watch X / 19500.90 / 54 / Electronics. The prompt asks for table construction and alteration, not insertion statements.',['4 marks for a valid CREATE TABLE definition covering the required fields, text lengths, primary key and suitable numeric types.','1 mark for dropping Category.','1 mark for adding Brand with length 15.','1 mark for altering Product_Name to TEXT(40).','Accept compatible Access SQL data-type synonyms. The current syllabus uses MS SQL, whose syntax differs, so retain the historical Access dialect when marking this paper.'],'12:11.9.5')
assert len(rows)==10 and sum(q['marks'] for q in rows if not q['number'].endswith('b'))==35
(ROOT/'data/computer-science/hssc_xi_2024_written.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('10 written entries and project-authored marking rubrics')
